package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.get;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class ConditionalClocksAcceptance {
 static final String API="/api/openservice/clock-policies";
 static Map<String,Object> config(String calendar,int revision){return map("revision",revision,"active",true,"definition",map("name","Priority service commitment <script>","table","incident","calendar",calendar,"minutes",120,"purpose","resolution","max_priority",2,"start",List.of("1","2"),"pause",List.of("3"),"complete",List.of("6"),"cancel",List.of("7")));}
 static String calendar(WorkflowSupport h)throws Exception{String id="Policy"+Values.id();BusinessDeadlineAcceptance.seed(h.store,id,PlatformFoundationTest.calendar());return id;}
 static String configure(WorkflowSupport h,Map<String,Object> input)throws Exception{return object(result(h.json("POST",API,input,auth("admin"))).get("policy")).get("policy_id").toString();}
 static String create(WorkflowSupport h,String priority,String user)throws Exception{return result(h.json("POST","/api/now/table/incident",map("short_description","Automatically timed service","priority",priority),auth(user))).get("sys_id").toString();}
 static Map<String,Object> update(WorkflowSupport h,String record,Object fields,String user)throws Exception{return result(h.json("PATCH","/api/now/table/incident/"+record,fields,auth(user)));}
 static Map<String,Object> page(WorkflowSupport h,String record,String user)throws Exception{return get(h,PlatformOperationsAcceptance.ROOT+"clocks/"+record+"?table=incident",user);}
 static Map<String,Object> binding(WorkflowSupport h,String record)throws Exception{return objects(page(h,record,"admin").get("policies")).getFirst();}
 static Map<String,Object> clock(WorkflowSupport h,String record)throws Exception{String id=binding(h,record).get("sla_id").toString();try(var db=h.store.open()){return db.one("SELECT * FROM os_sla WHERE sla_id=?",id);}}
 static void run(WorkflowSupport h)throws Exception {
  h.account("ClockPolicyAgent","agent");String calendar=calendar(h),policy=configure(h,config(calendar,0));String record=create(h,"2","ClockPolicyAgent");assertEquals("running",clock(h,record).get("state"));assertEquals("resolution",clock(h,record).get("purpose"));String clock=clock(h,record).get("sla_id").toString();update(h,record,map("description","Same condition"),"ClockPolicyAgent");assertEquals(1,objects(binding(h,record).get("history")).size());update(h,record,map("state","2"),"ClockPolicyAgent");assertEquals(clock,clock(h,record).get("sla_id"));update(h,record,map("state","3"),"ClockPolicyAgent");assertEquals("paused",clock(h,record).get("state"));long remaining=((Number)clock(h,record).get("remaining_ms")).longValue();SlaAlertsAcceptance.tick(h.store,System.currentTimeMillis()+3600000);assertEquals(remaining,((Number)clock(h,record).get("remaining_ms")).longValue());update(h,record,map("state","2"),"ClockPolicyAgent");assertEquals("running",clock(h,record).get("state"));update(h,record,map("state","6"),"ClockPolicyAgent");assertEquals("completed",clock(h,record).get("state"));update(h,record,map("state","7"),"ClockPolicyAgent");assertEquals("completed",clock(h,record).get("state"));assertEquals(4,objects(binding(h,record).get("history")).size());new Store(h.environment);assertEquals(clock,clock(h,record).get("sla_id"));assertEquals(true,get(h,API+"/"+policy,"admin").get("used"));
  var disabled=config(calendar,1);disabled.put("active",false);result(h.json("POST",API+"/"+policy,disabled,auth("admin")));assertTrue(objects(page(h,create(h,"1","admin"),"admin").get("clocks")).isEmpty());
 }
 static void configuration(WorkflowSupport h)throws Exception {
  String calendar=calendar(h),policy=configure(h,config(calendar,0));var change=config(calendar,1);object(change.get("definition")).put("name","Updated unused policy");result(h.json("POST",API+"/"+policy,change,auth("admin")));assertEquals(409,h.json("POST",API+"/"+policy,change,auth("admin")).statusCode());assertEquals(404,h.json("POST",API+"/"+id(),change,auth("admin")).statusCode());assertEquals(404,h.get(API+"/"+id(),auth("admin")).statusCode());assertEquals(400,h.get(API+"?extra=1",auth("admin")).statusCode());assertEquals(405,h.json("DELETE",API,map(),auth("admin")).statusCode());assertEquals(401,h.get(API,null).statusCode());
  for(var invalid:List.of(map("extra",1),map("active","true"),map("revision","0"))) {var input=config(calendar,0);input.putAll(invalid);assertEquals(400,h.json("POST",API,input,auth("admin")).statusCode());}
  for(var invalid:List.of(map("extra",1),map("name",""),map("table","cmdb_ci"),map("calendar","absent"),map("minutes","120"),map("minutes",0),map("minutes",525601),map("purpose","unknown"),map("max_priority","2"),map("max_priority",-1),map("max_priority",6),map("start","bad"),map("start",Collections.nCopies(101,"1")),map("start",List.of()),map("start",List.of(1)),map("start",List.of("unknown")),map("start",List.of("1","1")),map("pause",List.of("1")))){var input=config(calendar,0);object(input.get("definition")).putAll(invalid);assertEquals(400,h.json("POST",API,input,auth("admin")).statusCode(),invalid.toString());}
  var noPriority=config(calendar,0);object(noPriority.get("definition")).putAll(map("table","project","start",List.of("planning"),"pause",List.of(),"complete",List.of(),"cancel",List.of()));assertEquals(400,h.json("POST",API,noPriority,auth("admin")).statusCode());
  String record=create(h,"1","admin");var frozen=config(calendar,2);object(frozen.get("definition")).put("name","Changed used meaning");assertEquals(409,h.json("POST",API+"/"+policy,frozen,auth("admin")).statusCode());assertEquals("running",clock(h,record).get("state"));
  assertEquals(400,h.protectedForm("/admin/clock-policies",map("table","incident"),auth("admin")).statusCode());var form=form(calendar);form.put("active","yes");assertEquals(400,h.protectedForm("/admin/clock-policies",form,auth("admin")).statusCode());form=form(calendar);form.put("state_1","bad");assertEquals(400,h.protectedForm("/admin/clock-policies",form,auth("admin")).statusCode());
 }
 static Map<String,Object> form(String calendar){return map("name","Form policy","table","incident","calendar",calendar,"minutes","120","purpose","general","max_priority","0","active","true","revision","0","state_1","start","state_2","ignore","state_3","pause","state_6","complete","state_7","cancel");}
 static void authority(WorkflowSupport h)throws Exception {
  h.account("ClockOwner","admin");h.account("ClockPolicyReader","reader");h.account("ClockWriter","agent");String calendar=calendar(h),policy=object(result(h.json("POST",API,config(calendar,0),auth("ClockOwner"))).get("policy")).get("policy_id").toString();String uid=FieldDispatchAcceptance.uid(h,"ClockOwner");assertEquals(403,h.get(API,auth("ClockPolicyReader")).statusCode());assertEquals(403,h.json("POST",API,config(calendar,0),auth("ClockWriter")).statusCode());
  for(String setting:List.of("active=0","role='agent'","password_reset_required=1")){try(var db=h.store.open()){db.update("UPDATE os_user SET "+setting+" WHERE user_id=?",uid);db.connection.commit();}String record=create(h,"1","ClockWriter");assertTrue(objects(page(h,record,"admin").get("clocks")).isEmpty());assertEquals("owner_unavailable",objects(get(h,API,"admin").get("policies")).getFirst().get("authority"));try(var db=h.store.open()){db.update("UPDATE os_user SET active=1,role='admin',password_reset_required=0 WHERE user_id=?",uid);db.connection.commit();}update(h,record,map("description","Authority restored"),"ClockWriter");assertEquals("running",clock(h,record).get("state"));}
  String record=create(h,"1","admin");Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"incident");}var denied=new LinkedHashMap<>(schema);denied.put("record_roles",map("read",List.of("agent")));ReferencePickerAcceptance.writeSchema(h,"incident",denied);try{assertEquals(403,h.get(API+"/"+policy,auth("admin")).statusCode());update(h,record,map("state","2"),"ClockWriter");update(h,record,map("state","3"),"ClockWriter");try(var db=h.store.open()){assertEquals("running",db.one("SELECT state FROM os_sla WHERE record_id=?",record).get("state"));}assertEquals("table_read_unavailable",objects(get(h,API+"?table=problem","admin").get("policies")).getFirst().get("authority"));}finally{ReferencePickerAcceptance.writeSchema(h,"incident",schema);}update(h,record,map("description","Resume current authority"),"ClockWriter");assertEquals("paused",clock(h,record).get("state"));ProblemInvestigationsAcceptance.access(h,"incident",record,"private",FieldDispatchAcceptance.uid(h,"admin"));assertEquals(404,h.get(PlatformOperationsAcceptance.ROOT+"clocks/"+record+"?table=incident",auth("ClockWriter")).statusCode());assertEquals(404,h.get("/record/incident/"+record+"/clocks",auth("ClockWriter")).statusCode());
 }
 static void conflicts(WorkflowSupport h)throws Exception {
  String calendar=calendar(h);var input=config(calendar,0);object(input.get("definition")).put("start",List.of("2"));String policy=configure(h,input),record=create(h,"1","admin");String manual=PlatformOperationsAcceptance.post(h,"clocks",map("table","incident","record_id",record,"calendar",calendar,"minutes",120,"purpose","resolution")).get("sla_id").toString();update(h,record,map("state","2"),"admin");assertEquals("blocked_by_active_purpose",binding(h,record).get("last_outcome"));update(h,record,map("description","Still blocked"),"admin");assertEquals(1,objects(binding(h,record).get("history")).size());assertEquals(false,get(h,API+"/"+policy,"admin").get("used"));PlatformOperationsAcceptance.post(h,"clocks/"+manual,map("operation","cancel"));update(h,record,map("description","Retry after manual cancellation"),"admin");assertEquals("attached",binding(h,record).get("last_outcome"));assertEquals(2,objects(binding(h,record).get("history")).size());String attached=clock(h,record).get("sla_id").toString();assertNotEquals(manual,attached);var disabled=config(calendar,1);object(disabled.get("definition")).put("start",List.of("2"));disabled.put("active",false);result(h.json("POST",API+"/"+policy,disabled,auth("admin")));update(h,record,map("state","3"),"admin");assertEquals("paused",clock(h,record).get("state"));assertEquals(1,object(objects(binding(h,record).get("history")).getFirst().get("detail")).get("policy_revision"));
  String otherCalendar=calendar(h);var second=config(otherCalendar,0);object(second.get("definition")).put("purpose","general");configure(h,second);try(var db=h.store.open()){db.update("DELETE FROM os_calendar WHERE calendar_id=?",otherCalendar);db.connection.commit();}String unavailable=create(h,"1","admin");assertEquals("calendar_unavailable",binding(h,unavailable).get("last_outcome"));BusinessDeadlineAcceptance.seed(h.store,otherCalendar,PlatformFoundationTest.calendar());update(h,unavailable,map("description","Restored calendar"),"admin");assertEquals("running",clock(h,unavailable).get("state"));
 }
 static void lifecycle(WorkflowSupport h)throws Exception {
  String calendar=calendar(h);var input=config(calendar,0);object(input.get("definition")).putAll(map("purpose","general","max_priority",0,"complete",List.of("7"),"cancel",List.of("6")));configure(h,input);String record=create(h,"5","admin");update(h,record,map("state","2"),"admin");update(h,record,map("state","6"),"admin");assertEquals("cancelled",clock(h,record).get("state"));update(h,record,map("state","7"),"admin");assertEquals("cancelled",clock(h,record).get("state"));
  String breach=create(h,"1","admin"),clock=clock(h,breach).get("sla_id").toString();try(var db=h.store.open()){db.update("UPDATE os_sla SET last_tick=?,remaining_ms=1 WHERE sla_id=?",SlaAlertsAcceptance.START,clock);db.connection.commit();}SlaAlertsAcceptance.tick(h.store,SlaAlertsAcceptance.START+60000);update(h,breach,map("state","2"),"admin");assertEquals("breached",clock(h,breach).get("state"));update(h,breach,map("state","3"),"admin");assertEquals("breached",clock(h,breach).get("state"));update(h,breach,map("state","2"),"admin");update(h,breach,map("state","6"),"admin");assertEquals("cancelled",clock(h,breach).get("state"));assertTrue(((Number)clock(h,breach).get("breached_at")).longValue()>0);
  String during=create(h,"1","admin"),duringClock=clock(h,during).get("sla_id").toString();try(var db=h.store.open()){db.update("UPDATE os_sla SET last_tick=?,remaining_ms=1 WHERE sla_id=?",SlaAlertsAcceptance.START,duringClock);db.connection.commit();}update(h,during,map("state","2"),"admin");update(h,during,map("state","3"),"admin");assertEquals("breached",clock(h,during).get("state"));
  String removed=create(h,"1","admin"),removedClock=clock(h,removed).get("sla_id").toString();try(var db=h.store.open()){db.update("DELETE FROM os_sla WHERE sla_id=?",removedClock);db.connection.commit();}update(h,removed,map("state","2"),"admin");assertTrue(objects(page(h,removed,"admin").get("clocks")).isEmpty());
 }
 static void capacity(WorkflowSupport h)throws Exception {
  String calendar=calendar(h),policy=configure(h,config(calendar,0));String low=create(h,"5","admin");assertTrue(objects(page(h,low,"admin").get("clocks")).isEmpty());update(h,low,map("priority","1"),"admin");assertEquals("running",clock(h,low).get("state"));update(h,low,map("state","2"),"admin");for(int n=0;n<52;n++){update(h,low,map("state","3"),"admin");update(h,low,map("state","2"),"admin");}assertEquals(100,objects(binding(h,low).get("history")).size());assertEquals(105,((Number)binding(h,low).get("revision")).intValue());
  try(var db=h.store.open()){var row=db.one("SELECT * FROM os_clock_policy WHERE policy_id=?",policy);for(int n=1;n<100;n++)db.update("INSERT INTO os_clock_policy(policy_id,name,table_name,definition,active,revision,owner_id) VALUES(?,?,?,?,0,1,?)",id(),"Retained policy "+n,"incident",JSON.writeValueAsString(row.get("definition")),row.get("owner_id"));db.connection.commit();}assertEquals(100,objects(get(h,API,"admin").get("policies")).size());assertEquals(400,h.json("POST",API,config(calendar,0),auth("admin")).statusCode());
 }
 static void edges(WorkflowSupport h)throws Exception {
  String calendar=calendar(h);configure(h,config(calendar,0));String complete=create(h,"5","admin");update(h,complete,map("state","2"),"admin");update(h,complete,map("state","6"),"admin");assertTrue(objects(page(h,complete,"admin").get("clocks")).isEmpty());update(h,complete,map("state","7"),"admin");assertTrue(objects(page(h,complete,"admin").get("clocks")).isEmpty());
  String record=create(h,"1","admin"),clock=clock(h,record).get("sla_id").toString();update(h,record,map("state","2"),"admin");try(var db=h.store.open()){db.update("UPDATE os_sla SET last_tick=?,remaining_ms=1 WHERE sla_id=?",SlaAlertsAcceptance.START,clock);db.connection.commit();}SlaAlertsAcceptance.tick(h.store,SlaAlertsAcceptance.START+60000);update(h,record,map("state","6"),"admin");assertEquals("completed",clock(h,record).get("state"));assertTrue(((Number)clock(h,record).get("breached_at")).longValue()>0);
  String atCompletion=create(h,"1","admin"),atClock=clock(h,atCompletion).get("sla_id").toString();update(h,atCompletion,map("state","2"),"admin");try(var db=h.store.open()){db.update("UPDATE os_sla SET last_tick=?,remaining_ms=1 WHERE sla_id=?",SlaAlertsAcceptance.START,atClock);db.connection.commit();}update(h,atCompletion,map("state","6"),"admin");assertEquals("completed",clock(h,atCompletion).get("state"));assertTrue(((Number)clock(h,atCompletion).get("breached_at")).longValue()>0);
 }
 static void disableUnavailable(WorkflowSupport h)throws Exception {
  String calendar=calendar(h),policy=configure(h,config(calendar,0)),record=create(h,"1","admin");try(var db=h.store.open()){db.update("DELETE FROM os_calendar WHERE calendar_id=?",calendar);db.connection.commit();}var result=result(h.json("POST",API+"/"+policy,map("revision",1,"active",false),auth("admin")));assertEquals(0,object(result.get("policy")).get("active"));update(h,record,map("state","2"),"admin");update(h,record,map("state","3"),"admin");assertEquals("paused",clock(h,record).get("state"));assertTrue(objects(page(h,create(h,"1","admin"),"admin").get("clocks")).isEmpty());assertEquals(400,h.json("POST",API,map("revision",0,"active",false),auth("admin")).statusCode());assertEquals(400,h.protectedForm("/admin/clock-policies/"+policy,map("revision","2","active","invalid"),auth("admin")).statusCode());assertEquals(302,h.protectedForm("/admin/clock-policies/"+policy,map("revision","2","active","false"),auth("admin")).statusCode());
 }
 static void concurrency(WorkflowSupport h)throws Exception {
  String calendar=calendar(h);configure(h,config(calendar,0));String record=create(h,"5","admin");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var signal=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{signal.await();return update(h,record,map("priority","1"),"admin");});var b=pool.submit(()->{signal.await();return update(h,record,map("priority","1"),"admin");});signal.countDown();a.get();b.get();}assertEquals(1,objects(page(h,record,"admin").get("clocks")).size());assertEquals(1,objects(binding(h,record).get("history")).size());
 }
}
